<template><section class="workspace"><div class="page-heading"><div><h1>会话管理</h1><p>查看当前账号已登录的设备，并撤销不再使用的会话。</p></div><el-button type="danger" plain :icon="Delete" @click="revokeAll">撤销全部会话</el-button></div><el-table v-loading="loading" :data="sessions" stripe><el-table-column label="设备" min-width="240"><template #default="{row}"><strong>{{ describeAgent(row.user_agent) }}</strong><div class="muted">{{ row.user_agent || '未知客户端' }}</div></template></el-table-column><el-table-column prop="ip_address" label="IP 地址" width="150"/><el-table-column label="最近活动" width="180"><template #default="{row}">{{ formatDate(row.last_seen_at) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag v-if="row.current" type="success">当前</el-tag><el-tag v-else-if="row.revoked_at" type="info">已撤销</el-tag><el-tag v-else>有效</el-tag></template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{row}"><el-button text type="danger" :disabled="!!row.revoked_at" @click="revoke(row.id)">撤销</el-button></template></el-table-column></el-table><el-empty v-if="!loading && !sessions.length" description="暂无会话"/></section></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{Delete}from'@element-plus/icons-vue';import{ElMessage,ElMessageBox}from'element-plus';import{enterpriseAPI}from'@/api/enterprise';import{useEnterpriseAuthStore}from'@/stores/enterpriseAuth';import type{EnterpriseSession}from'@/types/enterprise';const sessions=ref<EnterpriseSession[]>([]),loading=ref(false),auth=useEnterpriseAuthStore();const formatDate=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v));const describeAgent=(v:string)=>/mobile|android|iphone/i.test(v)?'移动设备':'桌面浏览器';async function load(){loading.value=true;try{sessions.value=await enterpriseAPI.listSessions()}finally{loading.value=false}}async function revoke(id:string){await ElMessageBox.confirm('确定撤销这个会话？','撤销会话',{type:'warning'});await enterpriseAPI.revokeSession(id);if(sessions.value.find(s=>s.id===id)?.current)auth.clear();ElMessage.success('会话已撤销');await load()}async function revokeAll(){await ElMessageBox.confirm('这会让当前账号在所有设备上退出登录。','撤销全部会话',{type:'warning'});await enterpriseAPI.revokeAllSessions();auth.clear();window.location.href='/enterprise/login'}onMounted(load);</script>
<style scoped>.workspace{min-width:0}.page-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.page-heading h1{margin:0 0 6px;font-size:26px}.page-heading p,.muted{margin:0;color:#64748b}.muted{max-width:440px;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}@media(max-width:640px){.page-heading{flex-direction:column}.page-heading .el-button{width:100%}}</style>
